css:
.turnsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1a2230;
    background: linear-gradient(165deg, #eef1f6 0%, #e2e7f0 100%);
    border-radius: 18px;
}

.turnsim-container * {
    box-sizing: border-box;
}

.turnsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #10203b 0%, #1d3357 52%, #29456f 100%);
    color: #f3f6fb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(16, 32, 59, 0.32);
    position: relative;
    overflow: hidden;
}

.turnsim-header::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: 0;
    width: 100%;
    height: 4px;
    background: repeating-linear-gradient(90deg, #f2a922 0 26px, #10203b 26px 44px);
    opacity: 0.85;
}

.turnsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.turnsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd98a;
    background: rgba(255, 255, 255, 0.10);
    padding: 5px 14px;
    border-radius: 999px;
}

.turnsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dde6f2;
}

.turnsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #28405f;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.turnsim-period-counter #currentDay,
.turnsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #10203b;
}

.turnsim-round-name {
    background: #d4ddec;
    color: #10203b;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.turnsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4b12;
    background: #fdebd2;
    padding: 4px 12px;
    border-radius: 999px;
}

.turnsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.turnsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6deeb;
    box-shadow: 0 4px 14px rgba(16, 32, 59, 0.06);
    border-top: 4px solid #29456f;
}

.turnsim-card-engagement { border-top-color: #1f7a5a; }
.turnsim-card-progress { border-top-color: #2f6fb0; }
.turnsim-card-trust { border-top-color: #6a4fb0; }
.turnsim-card-roles { border-top-color: #c98a16; }

.turnsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5e6e85;
}

.turnsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #10203b;
}

.turnsim-card-engagement .turnsim-value { color: #1f7a5a; }
.turnsim-card-progress .turnsim-value { color: #2f6fb0; }
.turnsim-card-trust .turnsim-value { color: #6a4fb0; }
.turnsim-card-roles .turnsim-value { color: #c98a16; }

.turnsim-sublabel {
    font-size: 0.76rem;
    color: #6f7e93;
    line-height: 1.35;
}

.turnsim-engagement-low .turnsim-value { color: #c0392b; }
.turnsim-engagement-strong .turnsim-value { color: #1f7a5a; }

.turnsim-roles-cut { border-top-color: #c0392b; }
.turnsim-roles-cut .turnsim-value { color: #c0392b; }

.turnsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #10203b;
    color: #eaf0f8;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.turnsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ffd98a;
}

.turnsim-budget-over #budgetDisplay {
    color: #ff9c7a;
}

.turnsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #f2a922;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(16, 32, 59, 0.05);
}

.turnsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.turnsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #10203b;
    margin-bottom: 6px;
}

.turnsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2c3a4f;
}

.turnsim-briefing-text strong { color: #1f7a5a; }
.turnsim-briefing-text em { color: #9a4b12; font-style: italic; }

.turnsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6deeb;
    box-shadow: 0 4px 14px rgba(16, 32, 59, 0.06);
}

.turnsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #10203b;
    border-bottom: 2px solid #e3e9f2;
    padding-bottom: 8px;
}

.turnsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #1d3357;
    margin: 14px 0 6px;
}

.turnsim-container select,
.turnsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #b6c4da;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6f9fd;
    color: #1a2230;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.turnsim-container select:focus,
.turnsim-container input[type="number"]:focus {
    outline: none;
    border-color: #29456f;
    box-shadow: 0 0 0 3px rgba(41, 69, 111, 0.16);
}

.turnsim-container select option {
    background-color: #ffffff;
    color: #1a2230;
}

.turnsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #29456f;
}

.turnsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1d3357;
    margin-top: 4px;
}

.turnsim-range-readout span:last-child {
    color: #1f7a5a;
    font-weight: 800;
}

.turnsim-hint {
    font-size: 0.8rem;
    color: #6f7e93;
    margin-top: 4px;
    line-height: 1.4;
}

.turnsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.turnsim-container .btn-primary {
    background: linear-gradient(135deg, #1d3357 0%, #29456f 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(29, 51, 87, 0.30);
}

.turnsim-container .btn-primary:hover {
    filter: brightness(1.1);
}

.turnsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #b6c4da;
    color: #5e6e85;
}

.turnsim-coach {
    background: linear-gradient(135deg, #10203b 0%, #1d3357 100%);
    color: #eaf0f8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(16, 32, 59, 0.24);
    border-left: 5px solid #f2a922;
}

.turnsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffd98a;
    margin-bottom: 8px;
}

.turnsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.turnsim-coach-body strong { color: #ffd98a; }
.turnsim-coach-body em { color: #ffc1ad; font-style: italic; }

.turnsim-history,
.turnsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6deeb;
    box-shadow: 0 4px 14px rgba(16, 32, 59, 0.06);
}

.turnsim-history h3,
.turnsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #10203b;
}

.turnsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #1d3357;
}

.turnsim-container table#usfHistoryTable th {
    background: #e9eef6;
    color: #10203b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d2dcea;
}

.turnsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f8;
}

.turnsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7fafd;
}

.turnsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .turnsim-container {
        padding: 14px;
    }
    .turnsim-header h1 {
        font-size: 1.7rem;
    }
    .turnsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .turnsim-value {
        font-size: 2rem;
    }
    .turnsim-clock {
        margin-left: 0;
    }
    .turnsim-period-counter {
        font-size: 0.88rem;
    }
    .turnsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .turnsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.turnsim-completion { padding: 8px 4px 4px; }
.turnsim-cm-head { text-align: center; margin-bottom: 16px; }
.turnsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f7a5a; }
.turnsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #5a6b86; }
.turnsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #1d3357; }
.turnsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.turnsim-cm-yes { background: rgba(31,122,90,0.15); color: #176a4d; border: 1px solid rgba(31,122,90,0.42); }
.turnsim-cm-no { background: rgba(192,57,43,0.12); color: #c0392b; border: 1px solid rgba(192,57,43,0.4); }
.turnsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.turnsim-cm-metric { flex: 1 1 120px; min-width: 108px; background: #f2f6fb; border: 1px solid #d3ddec; border-radius: 10px; padding: 10px 8px; text-align: center; }
.turnsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #1f7a5a; }
.turnsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a6b86; text-transform: uppercase; letter-spacing: 0.03em; }
.turnsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #1d3357; }
.turnsim-cm-insights { margin: 0; padding-left: 20px; }
.turnsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #24344f; }

