(function() {
    'use strict';

    class TurnAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Leading the Turn`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_ENGAGEMENT = 41;   // below UK norm; the human-centered KPI
            this.START_PROGRESS = 12;     // little credible transformation yet
            this.START_TRUST = 35;        // board/clients/union after the −18% shock
            this.AFFECTED_ROLES = 900;    // roles exposed by automation of two depots
            this.COMPULSORY_COST = 9;     // GBP 9M redundancy cost (~£10k/role)
            this.BUDGET_CAP = 60;         // GBP 60M over three years, in millions
            this.FCF = 22;                // GBP 22M annual free cash flow

            // Targets used in the debrief.
            this.ENGAGEMENT_TARGET = 55;  // UK norm — a credible "people" turn
            this.PROGRESS_TARGET = 60;    // credible, client-visible transformation
            this.TRUST_TARGET = 55;

            // Concept truths (the human-centered transformation).
            this.TRUE_TYPE = `survival`;
            this.TRUE_PROBLEM = `human`;
            this.TRUE_HARDEST = `union`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    engagement: this.START_ENGAGEMENT,
                    progress: this.START_PROGRESS,
                    trust: this.START_TRUST,
                    rolesProtected: this.AFFECTED_ROLES,
                    budgetUsed: 0,
                    strike: false,
                    overPromised: false,
                    anchorLost: false,
                    engagementHistory: [this.START_ENGAGEMENT],
                    progressHistory: [this.START_PROGRESS],
                    trustHistory: [this.START_TRUST],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    type: `survival`,
                    problem: `human`,
                    hardest: `union`,
                    rigour: 60,
                    spine: `purpose`,
                    firstmove: `listen`,
                    audience: `tailored`,
                    silence: `honest`,
                    rollout: `phased`,
                    workforce: `redeploy`,
                    invest: 30,
                    wins: 55,
                    capacity: 60,
                    recovery: `hold`,
                    leak: `front`,
                    update: `honest`,
                    consistency: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ty = document.getElementById(`typeInput`);
                const pr = document.getElementById(`problemInput`);
                const ha = document.getElementById(`hardestInput`);
                const ri = document.getElementById(`rigourInput`);
                if (ty) decisions.type = ty.value;
                if (pr) decisions.problem = pr.value;
                if (ha) decisions.hardest = ha.value;
                if (ri) decisions.rigour = parseInt(ri.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const sp = document.getElementById(`spineInput`);
                const fm = document.getElementById(`firstmoveInput`);
                const au = document.getElementById(`audienceInput`);
                const si = document.getElementById(`silenceInput`);
                if (sp) decisions.spine = sp.value;
                if (fm) decisions.firstmove = fm.value;
                if (au) decisions.audience = au.value;
                if (si) decisions.silence = si.value;
            } else if (round === 3) {
                const ro = document.getElementById(`rolloutInput`);
                const wf = document.getElementById(`workforceInput`);
                const inv = document.getElementById(`investInput`);
                const wi = document.getElementById(`winsInput`);
                const ca = document.getElementById(`capacityInput`);
                if (ro) decisions.rollout = ro.value;
                if (wf) decisions.workforce = wf.value;
                if (inv) decisions.invest = parseFloat(inv.value);
                if (wi) decisions.wins = parseInt(wi.value, 10);
                if (ca) decisions.capacity = parseInt(ca.value, 10);
                if (!Number.isFinite(decisions.invest) || decisions.invest < 0) {
                    warn(`warn_invest_negative`); return false;
                }
                const remaining = this.BUDGET_CAP - state.domainState.budgetUsed;
                if (decisions.invest > remaining + 0.001) {
                    warn(`warn_invest_cap`); return false;
                }
                if (!Number.isFinite(decisions.wins) || decisions.wins < 0 || decisions.wins > 100) {
                    warn(`warn_wins_range`); return false;
                }
                if (!Number.isFinite(decisions.capacity) || decisions.capacity < 0 || decisions.capacity > 100) {
                    warn(`warn_capacity_range`); return false;
                }
            } else if (round === 4) {
                const re = document.getElementById(`recoveryInput`);
                const le = document.getElementById(`leakInput`);
                const up = document.getElementById(`updateInput`);
                const co = document.getElementById(`consistencyInput`);
                if (re) decisions.recovery = re.value;
                if (le) decisions.leak = le.value;
                if (up) decisions.update = up.value;
                if (co) decisions.consistency = parseInt(co.value, 10);
                if (!Number.isFinite(decisions.consistency) || decisions.consistency < 0 || decisions.consistency > 100) {
                    warn(`warn_consistency_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // engagement = the human-centered KPI; progress = credible client-visible transformation;
            // trust = board/client/union confidence; rolesCut = roles lost; spend = GBP M committed.
            let engDelta = 0, progDelta = 0, trustDelta = 0, rolesCut = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the turn — human problem first, not technology-first (Common Error 1).
                if (d.type === this.TRUE_TYPE) {
                    progDelta += 6; trustDelta += 5; coachKey = `coach_r1_survival`;
                } else if (d.type === `efficiency`) {
                    engDelta -= 4; progDelta += 2; coachKey = `coach_r1_efficiency`;
                } else if (d.type === `growth`) {
                    progDelta -= 2; trustDelta -= 3; coachKey = `coach_r1_growth`;
                } else {
                    engDelta -= 5; progDelta -= 4; trustDelta -= 3; coachKey = `coach_r1_bauplus`;
                }

                if (d.problem === this.TRUE_PROBLEM) {
                    engDelta += 10; trustDelta += 4;
                    if (d.type === this.TRUE_TYPE) coachKey = `coach_r1_diag_sharp`;
                } else if (d.problem === `technology`) {
                    engDelta -= 10; progDelta += 3; coachKey = `coach_r1_techfirst`;
                } else if (d.problem === `cost`) {
                    engDelta -= 8; trustDelta -= 4; coachKey = `coach_r1_costfirst`;
                } else {
                    engDelta += 1; coachKey = `coach_r1_strategy`;
                }

                // The frontline is the stakeholder you must convert, not merely manage.
                if (d.hardest === this.TRUE_HARDEST) { engDelta += 6; trustDelta += 2; }
                else if (d.hardest === `board` || d.hardest === `analysts`) { engDelta -= 5; coachKey = `coach_r1_wrongstake`; }

                // Rigour: depth of human-factor diagnosis before any costing.
                if (d.rigour >= 60) { engDelta += 6; }
                else if (d.rigour <= 25) { engDelta -= 7; coachKey = `coach_r1_shallow`; }

                summaryKey = (d.problem === this.TRUE_PROBLEM && d.type === this.TRUE_TYPE) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Frame the why before the what (Common Errors 2 & 5).
                switch (d.spine) {
                    case `purpose`: engDelta += 12; trustDelta += 4; coachKey = `coach_r2_purpose`; break;
                    case `burning`: engDelta -= 12; trustDelta -= 3; coachKey = `coach_r2_burning`; break;
                    case `vision`: engDelta += 3; progDelta += 1; coachKey = `coach_r2_vision`; break;
                    case `numbers`: engDelta -= 3; trustDelta += 2; coachKey = `coach_r2_numbers`; break;
                }

                // First move and its order.
                switch (d.firstmove) {
                    case `listen`: engDelta += 8; trustDelta += 3; break;
                    case `townhall`: engDelta += 1; break;
                    case `board`: engDelta -= 3; trustDelta += 4; coachKey = `coach_r2_boardfirst`; break;
                    case `client`: engDelta -= 5; progDelta += 2; coachKey = `coach_r2_clientfirst`; break;
                }

                // One coherent why, three audiences (Common Error 5).
                switch (d.audience) {
                    case `tailored`: engDelta += 9; trustDelta += 6; coachKey = (d.spine === `purpose`) ? `coach_r2_tailored` : coachKey; break;
                    case `onedeck`: engDelta -= 6; trustDelta -= 5; coachKey = `coach_r2_onedeck`; break;
                    case `boardonly`: engDelta -= 8; trustDelta -= 2; coachKey = `coach_r2_boardonly`; break;
                }

                // What not to say yet — the redundancy question.
                switch (d.silence) {
                    case `honest`: engDelta += 6; trustDelta += 4; break;
                    case `deny`: engDelta += 3; trustDelta -= 8; coachKey = `coach_r2_deny`; break;
                    case `silent`: engDelta -= 4; trustDelta -= 3; coachKey = `coach_r2_silent`; break;
                }

                progDelta += 3; // communicating the why builds early momentum
                summaryKey = (d.spine === `purpose` && d.audience === `tailored` && d.silence === `honest`) ? `sum_r2_good` : (d.spine === `burning` ? `sum_r2_fear` : `sum_r2_weak`);
            } else if (round === 3) {
                // Pace the change under the human-centered constraint (Common Errors 3 & 4).
                spend = d.invest;

                // Sequencing: pilot-and-scale lets you learn and prove a deliverable win.
                if (d.rollout === `phased`) { progDelta += 8; trustDelta += 3; coachKey = `coach_r3_phased`; }
                else { progDelta += 5; engDelta -= 5; coachKey = `coach_r3_bigbang`; }

                // Workforce commitment for the ~900 affected roles.
                if (d.workforce === `redeploy`) {
                    engDelta += 12; trustDelta += 5; coachKey = (d.rollout === `phased`) ? `coach_r3_humancentered` : coachKey;
                } else if (d.workforce === `voluntary`) {
                    engDelta += 2; rolesCut = 220; coachKey = `coach_r3_voluntary`;
                } else {
                    // Compulsory cuts: ~£9M, near-certain strike, destroys the loyalty asset (Common Error 3).
                    engDelta -= 16; trustDelta -= 12; rolesCut = 900; spend += this.COMPULSORY_COST;
                    ds.strike = true; coachKey = `coach_r3_compulsory`;
                }

                // Investment level: under-invest loses the client; over-invest strains free cash flow.
                if (d.invest >= 25 && d.invest <= 40) { progDelta += 8; }
                else if (d.invest < 15) { progDelta -= 8; trustDelta -= 4; coachKey = `coach_r3_underinvest`; }
                else if (d.invest > 45) { progDelta += 5; trustDelta -= 5; coachKey = `coach_r3_overinvest`; }

                // Early wins: over-promising sets up a credibility loss when the slip hits in R4.
                if (d.wins >= 80) {
                    progDelta += 8; trustDelta += 4; ds.overPromised = true; coachKey = `coach_r3_overpromise`;
                } else if (d.wins >= 45) {
                    progDelta += 6; trustDelta += 5;
                } else {
                    progDelta += 2; trustDelta -= 2; coachKey = `coach_r3_timid`;
                }

                // Protecting capacity to absorb change — the constraint at the core.
                if (d.capacity >= 60) { engDelta += 8; progDelta += 2; }
                else if (d.capacity <= 25) { engDelta -= 8; coachKey = `coach_r3_nocapacity`; }

                summaryKey = (d.rollout === `phased` && d.workforce === `redeploy`) ? `sum_r3_good` : (d.workforce === `compulsory` ? `sum_r3_strike` : `sum_r3_weak`);
            } else if (round === 4) {
                // Hold the line through the trough (Common Error 4 + leading-through tests).
                switch (d.recovery) {
                    case `hold`: engDelta += 8; progDelta += 6; trustDelta += 4; coachKey = `coach_r4_hold`; break;
                    case `slow`: engDelta += 5; progDelta -= 2; trustDelta -= 2; coachKey = `coach_r4_slow`; break;
                    case `double`: engDelta -= 10; progDelta += 4; trustDelta -= 6; coachKey = `coach_r4_double`; break;
                }

                // The leak — leading through it vs around it.
                switch (d.leak) {
                    case `front`: engDelta += 9; trustDelta += 8; coachKey = (d.recovery === `hold`) ? `coach_r4_front` : coachKey; break;
                    case `holding`: engDelta -= 6; trustDelta -= 6; coachKey = `coach_r4_holding`; break;
                    case `silent`: engDelta -= 12; trustDelta -= 10; coachKey = `coach_r4_silent`; break;
                }

                // The board-and-client update — honesty on the slip vs spin/over-promise.
                switch (d.update) {
                    case `honest`: trustDelta += 8; progDelta += 4; break;
                    case `spin`: trustDelta -= 8; coachKey = `coach_r4_spin`; break;
                    case `overpromise`: trustDelta -= 6; ds.overPromised = true; coachKey = `coach_r4_overpromise`; break;
                }

                // An over-promised win from R3 now bites unless recovery + update are honest.
                if (ds.overPromised && !(d.update === `honest` && d.leak === `front`)) {
                    trustDelta -= 10; progDelta -= 4; coachKey = `coach_r4_promisebites`;
                }

                // Consistency with the Round 2 leader nudges engagement and trust.
                engDelta += Math.round((d.consistency - 60) / 10);
                trustDelta += Math.round((d.consistency - 60) / 12);

                summaryKey = (d.recovery !== `double` && d.leak === `front` && d.update === `honest`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Strike depresses engagement and progress every subsequent round it persists.
            if (ds.strike && round > 3) { engDelta -= 4; progDelta -= 3; }

            // Resource & headcount accounting.
            ds.budgetUsed = Math.min(this.BUDGET_CAP + this.COMPULSORY_COST, Math.round((ds.budgetUsed + spend) * 10) / 10);
            ds.rolesProtected = Math.max(0, ds.rolesProtected - rolesCut);

            // Apply deltas, clamped 0–100 (engagement is a %, the others a 0–100 index).
            ds.engagement = Math.max(0, Math.min(100, ds.engagement + engDelta));
            ds.progress = Math.max(0, Math.min(100, ds.progress + progDelta));
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));

            // Anchor client walks if, by the final round, neither progress nor trust is credible.
            if (round === this.ROUNDS.length && (ds.progress < 45 || ds.trust < 40)) ds.anchorLost = true;

            ds.engagementHistory.push(Math.round(ds.engagement));
            ds.progressHistory.push(Math.round(ds.progress));
            ds.trustHistory.push(Math.round(ds.trust));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite to the reporting/grading layer each period; final period locks the score.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                engagement: Math.round(ds.engagement),
                engagementDelta: Math.round(engDelta),
                progress: Math.round(ds.progress),
                progressDelta: Math.round(progDelta),
                trust: Math.round(ds.trust),
                trustDelta: Math.round(trustDelta),
                rolesProtected: ds.rolesProtected,
                budgetUsed: ds.budgetUsed,
                strike: ds.strike,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

