        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.engagementHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                turnChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.engagementHistory },
                        { data: ds.progressHistory },
                        { data: ds.trustHistory }
                    ]
                }
            };
        }

        // Shared composite (0-100). Written to domainState.performance.overallScore each period for
        // the reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const engagement = Math.round(ds.engagement || 0);
            const progress = Math.round(ds.progress || 0);
            const trust = Math.round(ds.trust || 0);
            const composite = Math.round(engagement * 0.35 + progress * 0.33 + trust * 0.32);
            return Math.max(0, Math.min(100, composite));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const engagement = Math.round(ds.engagement);
            const progress = Math.round(ds.progress);
            const trust = Math.round(ds.trust);

            const peopleHeld = engagement >= this.ENGAGEMENT_TARGET && ds.rolesProtected >= 680 && !ds.strike;
            const turnCredible = progress >= this.PROGRESS_TARGET && trust >= this.TRUST_TARGET;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            let performanceKey = `grade_stalled`;
            if (turnCredible && peopleHeld && composite >= 70) performanceKey = `grade_led`;
            else if (turnCredible && peopleHeld) performanceKey = `grade_credible`;
            else if (turnCredible && !peopleHeld) performanceKey = `grade_broke`;
            else if (peopleHeld && !turnCredible) performanceKey = `grade_lostmarket`;
            else if (composite >= 45) performanceKey = `grade_started`;
            const performance = T(performanceKey);

            const insights = [];
            if (turnCredible && peopleHeld) insights.push(window.mySimulation.t(`insight_led`));
            else if (turnCredible && !peopleHeld) insights.push(window.mySimulation.t(`insight_brokepeople`));
            else if (peopleHeld && !turnCredible) insights.push(window.mySimulation.t(`insight_lostmarket`));
            else insights.push(window.mySimulation.t(`insight_stalled`));

            if (ds.strike) insights.push(window.mySimulation.t(`insight_strike`));
            if (ds.anchorLost) insights.push(window.mySimulation.t(`insight_anchorlost`));
            if (ds.overPromised) insights.push(window.mySimulation.t(`insight_overpromised`));
            if (engagement < 40) insights.push(window.mySimulation.t(`insight_lowengagement`));
            if (turnCredible && peopleHeld && engagement >= 60) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                engagement: engagement,
                progress: progress,
                trust: trust,
                rolesProtected: ds.rolesProtected,
                strike: ds.strike,
                anchorLost: ds.anchorLost,
                turnCredible: turnCredible,
                peopleHeld: peopleHeld,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        // v1.1.0: render the computed grade, KPIs and insight debrief in the completion modal
        // instead of the framework generic "you completed N periods" fallback.
        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!(s.turnCredible && s.peopleHeld);
            const badge = met
                ? `<span class="turnsim-cm-badge turnsim-cm-yes">` + T(`cm_turn_led`) + `</span>`
                : `<span class="turnsim-cm-badge turnsim-cm-no">` + T(`cm_turn_incomplete`) + `</span>`;
            const strikeBadge = s.strike
                ? ` <span class="turnsim-cm-badge turnsim-cm-no">` + T(`cm_strike`) + `</span>`
                : ``;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="turnsim-cm-metric"><span class="turnsim-cm-mv">` + Math.round(s.engagement || 0) + `%</span><span class="turnsim-cm-ml">` + T(`cm_m_engagement`) + `</span></div>`
                + `<div class="turnsim-cm-metric"><span class="turnsim-cm-mv">` + Math.round(s.progress || 0) + `</span><span class="turnsim-cm-ml">` + T(`cm_m_progress`) + `</span></div>`
                + `<div class="turnsim-cm-metric"><span class="turnsim-cm-mv">` + Math.round(s.trust || 0) + `</span><span class="turnsim-cm-ml">` + T(`cm_m_trust`) + `</span></div>`
                + `<div class="turnsim-cm-metric"><span class="turnsim-cm-mv">` + Math.round(s.rolesProtected || 0) + `</span><span class="turnsim-cm-ml">` + T(`cm_m_roles`) + `</span></div>`;
            return ``
                + `<div class="turnsim-completion">`
                +   `<div class="turnsim-cm-head">`
                +     `<div class="turnsim-cm-score">` + score + `<span class="turnsim-cm-score-max">/100</span></div>`
                +     `<div class="turnsim-cm-grade">` + grade + ` ` + badge + strikeBadge + `</div>`
                +   `</div>`
                +   `<div class="turnsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="turnsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="turnsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.strike) return window.mySimulation.t(`hint_strike`);
            if (ds.overPromised && state.currentPeriod >= 3) return window.mySimulation.t(`hint_overpromise`);
            if (ds.engagement < 35) return window.mySimulation.t(`hint_engagement`);
            if (state.currentPeriod >= 3 && ds.progress < 40) return window.mySimulation.t(`hint_behind`);
            if (ds.engagement >= this.ENGAGEMENT_TARGET && ds.progress >= this.PROGRESS_TARGET && ds.trust >= this.TRUST_TARGET) return window.mySimulation.t(`hint_strong`);
            return null;
        }

